import json

data = json.load(open('/app/resources/treasury_bulletin_2021_12.json'))
doc = data.get('document', {})
elements = doc.get('elements', [])

# Look at a table element's content
for i, el in enumerate(elements):
    if el.get('type') == 'table':
        print(f"Table element {i}:")
        content = el.get('content', {})
        if isinstance(content, list):
            print(f"Content is list with {len(content)} rows")
            for row in content[:5]:
                print(row)
        else:
            print(f"Content: {content}")
        print("---")
        if i > 3:
            break
EOF
